if (pm.response.code === 200) {
    const body = pm.response.json();

    if (!body.access_token) {
        throw new Error("Token response missing access_token");
    }

    pm.collectionVariables.set("access_token", body.access_token);

    if (body.expires_in) {
        pm.collectionVariables.set(
            "token_expiry",
            String(Date.now() + (body.expires_in * 1000))
        );
    }

    if (body.refresh_token) {
        pm.collectionVariables.set("refresh_token", body.refresh_token);
    }

    console.log("Token acquired successfully");
} else {
    throw new Error(
        `Token request failed: ${pm.response.code} ${pm.response.text()}`
    );
}

const token = pm.collectionVariables.get("access_token");

if (!token) {
    throw new Error("Missing access_token. Token request likely failed.");
}

pm.test("Status is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response is JSON", function () {
    pm.expect(
        pm.response.headers.get("Content-Type")
    ).to.include("application/json");
});

pm.test("Response body is not empty", function () {
    const body = pm.response.json();
    pm.expect(body).to.exist;
});

